export function WidgetMenu({
  label = "{{label}}",
  open = {{open}},
  size = {{size}},
  color = "{{color}}",
}) {
  return (
    <details open={open} style={{ position: "relative", font: "13px system-ui, sans-serif", color: "#241430" }}>
      <summary aria-label={label + " widget options"} style={{ display: "inline-flex", alignItems: "center", justifyContent: "center", width: size, height: size, border: "1px solid #24143022", borderRadius: 6, background: "#FAF7F2", cursor: "pointer", listStyle: "none", color }}>⋯</summary>
      <ul style={{ position: "absolute", zIndex: 1, margin: "4px 0 0", padding: 6, listStyle: "none", border: "1px solid #24143022", borderRadius: 8, background: "#FAF7F2", minWidth: 120, boxShadow: "0 8px 20px rgba(36,20,48,.14)" }}>
        <li><button type="button" style={{ width: "100%", textAlign: "left", background: "none", border: "none", padding: "6px 8px", borderRadius: 6, cursor: "pointer", color: "#241430" }}>Refresh</button></li>
        <li><button type="button" style={{ width: "100%", textAlign: "left", background: "none", border: "none", padding: "6px 8px", borderRadius: 6, cursor: "pointer", color: "#241430" }}>Export</button></li>
        <li><button type="button" style={{ width: "100%", textAlign: "left", background: "none", border: "none", padding: "6px 8px", borderRadius: 6, cursor: "pointer", color: "#b3261e" }}>Remove</button></li>
      </ul>
    </details>
  );
}
